// ============ Bible places & basemap ============
//
// Data is generated by scripts/build-bible-geo.mjs and served from
// public/data/bible-geo/. Sources and licenses:
//  - Places & coordinates: OpenBible.info Bible Geocoding Data (CC BY 4.0)
//  - Place descriptions: Easton's Bible Dictionary (1897, public domain) via
//    Theographic Bible Metadata (CC BY-SA 4.0)
//  - Basemap: Natural Earth (public domain)

import type { FeatureCollection } from 'geojson';

export interface BiblePlace {
  id: string;
  name: string;
  type: string;
  lon: number;
  lat: number;
  /** 0–1000: scholarly confidence in this location */
  confidence: number;
  isWater: boolean;
  description?: string;
  url: string;
}

export interface ChapterPlace extends BiblePlace {
  /** Chapter the mention is in (useful for whole-book views) */
  chapter: number;
  verses: number[];
}

export interface Basemap {
  land: FeatureCollection;
  lakes: FeatureCollection;
  rivers: FeatureCollection;
}

export type ConfidenceLevel = 'confident' | 'likely' | 'uncertain';

export const GEO_ATTRIBUTION = {
  places: { label: 'OpenBible.info', url: 'https://www.openbible.info/geo/', license: 'CC BY 4.0' },
  descriptions: { label: "Easton's Bible Dictionary via Theographic", url: 'https://theographic.netlify.app/', license: 'CC BY-SA 4.0' },
  basemap: { label: 'Natural Earth', url: 'https://www.naturalearthdata.com/' },
};

// App book names -> OSIS codes used for the data files
export const OSIS: Record<string, string> = {
  Genesis: 'Gen', Exodus: 'Exod', Leviticus: 'Lev', Numbers: 'Num', Deuteronomy: 'Deut',
  Joshua: 'Josh', Judges: 'Judg', Ruth: 'Ruth', '1 Samuel': '1Sam', '2 Samuel': '2Sam',
  '1 Kings': '1Kgs', '2 Kings': '2Kgs', '1 Chronicles': '1Chr', '2 Chronicles': '2Chr',
  Ezra: 'Ezra', Nehemiah: 'Neh', Esther: 'Esth', Job: 'Job', Psalms: 'Ps', Proverbs: 'Prov',
  Ecclesiastes: 'Eccl', 'Song of Solomon': 'Song', Isaiah: 'Isa', Jeremiah: 'Jer',
  Lamentations: 'Lam', Ezekiel: 'Ezek', Daniel: 'Dan', Hosea: 'Hos', Joel: 'Joel', Amos: 'Amos',
  Obadiah: 'Obad', Jonah: 'Jonah', Micah: 'Mic', Nahum: 'Nah', Habakkuk: 'Hab',
  Zephaniah: 'Zeph', Haggai: 'Hag', Zechariah: 'Zech', Malachi: 'Mal', Matthew: 'Matt',
  Mark: 'Mark', Luke: 'Luke', John: 'John', Acts: 'Acts', Romans: 'Rom',
  '1 Corinthians': '1Cor', '2 Corinthians': '2Cor', Galatians: 'Gal', Ephesians: 'Eph',
  Philippians: 'Phil', Colossians: 'Col', '1 Thessalonians': '1Thess',
  '2 Thessalonians': '2Thess', '1 Timothy': '1Tim', '2 Timothy': '2Tim', Titus: 'Titus',
  Philemon: 'Phlm', Hebrews: 'Heb', James: 'Jas', '1 Peter': '1Pet', '2 Peter': '2Pet',
  '1 John': '1John', '2 John': '2John', '3 John': '3John', Jude: 'Jude', Revelation: 'Rev',
};

interface RawPlace {
  n: string;
  t: string;
  c: [number, number];
  q: number;
  w?: 1;
  d?: string;
  u: string;
}

interface RawBook {
  places: Record<string, RawPlace>;
  chapters: Record<string, [string, number[]][]>;
}

const BASE = `${import.meta.env.BASE_URL}data/bible-geo`;
let basemapPromise: Promise<Basemap> | null = null;
let detailPromise: Promise<Basemap> | null = null;
const bookCache = new Map<string, Promise<RawBook | null>>();

async function fetchJson<T>(url: string): Promise<T> {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`Failed to load ${url} (${res.status})`);
  return res.json() as Promise<T>;
}

export function loadBasemap(): Promise<Basemap> {
  basemapPromise ??= fetchJson<Basemap>(`${BASE}/basemap.json`).catch(err => {
    basemapPromise = null; // allow retry
    throw err;
  });
  return basemapPromise;
}

/** Higher-resolution coastlines and rivers for zoomed-in views (~1 MB, loaded on demand). */
export function loadBasemapDetail(): Promise<Basemap> {
  detailPromise ??= fetchJson<Basemap>(`${BASE}/basemap-detail.json`).catch(err => {
    detailPromise = null;
    throw err;
  });
  return detailPromise;
}

function loadBook(book: string): Promise<RawBook | null> {
  const osis = OSIS[book];
  if (!osis) return Promise.resolve(null);
  let p = bookCache.get(osis);
  if (!p) {
    p = fetchJson<RawBook>(`${BASE}/places/${osis}.json`).catch(err => {
      bookCache.delete(osis);
      throw err;
    });
    bookCache.set(osis, p);
  }
  return p;
}

function toPlace(id: string, raw: RawPlace): BiblePlace {
  return {
    id,
    name: raw.n,
    type: raw.t,
    lon: raw.c[0],
    lat: raw.c[1],
    confidence: raw.q,
    isWater: raw.w === 1,
    description: raw.d,
    url: raw.u,
  };
}

/** Places mentioned in a chapter, in order of first mention. */
export async function getChapterPlaces(book: string, chapter: number): Promise<ChapterPlace[]> {
  const data = await loadBook(book);
  if (!data) return [];
  return (data.chapters[String(chapter)] ?? [])
    .filter(([id]) => data.places[id])
    .map(([id, verses]) => ({ ...toPlace(id, data.places[id]), chapter, verses }));
}

/** Every place mentioned in a book, with the first chapter it appears in. */
export async function getBookPlaces(book: string): Promise<ChapterPlace[]> {
  const data = await loadBook(book);
  if (!data) return [];
  const seen = new Map<string, ChapterPlace>();
  const chapterNums = Object.keys(data.chapters).map(Number).sort((a, b) => a - b);
  for (const ch of chapterNums) {
    for (const [id, verses] of data.chapters[String(ch)]) {
      if (!seen.has(id) && data.places[id]) {
        seen.set(id, { ...toPlace(id, data.places[id]), chapter: ch, verses });
      }
    }
  }
  return [...seen.values()];
}

export function confidenceLevel(confidence: number): ConfidenceLevel {
  if (confidence >= 700) return 'confident';
  if (confidence >= 400) return 'likely';
  return 'uncertain';
}

export const CONFIDENCE_LABELS: Record<ConfidenceLevel, string> = {
  confident: 'Location confident',
  likely: 'Location likely',
  uncertain: 'Location uncertain',
};
